"""Rebuild source evidence inventory; no runtime performance claims."""
from pathlib import Path
import csv,re
r=Path(__file__).resolve().parents[2];t=r/'tools/connected_alpha'
paths=set((r/'TMessagesProj/src/main/java/app/flexygram').rglob('*.java'))
for name in ['org/telegram/ui/MainTabsLayout.java','org/telegram/ui/DialogsActivity.java','org/telegram/ui/ChatActivity.java','org/telegram/ui/ActionBar/ActionBarLayout.java','org/telegram/ui/ActionBar/ActionBarPopupWindow.java','org/telegram/ui/Components/FilterTabsView.java','org/telegram/ui/Components/ReactionsContainerLayout.java','org/telegram/ui/Components/ChatActivityEnterView.java','org/telegram/ui/Components/ChatAvatarContainer.java','org/telegram/ui/Cells/ChatMessageCell.java','org/telegram/ui/bots/BotKeyboardView.java','org/telegram/ui/Components/FragmentContextView.java','org/telegram/ui/PhotoViewer.java','app/exteraless/player/PlayerSheet.java','app/exteraless/player/PlayerBarView.java','app/exteraless/drawer/DrawerContainer.java']:
 f=r/'TMessagesProj/src/main/java'/name
 if f.is_file():paths.add(f)
with (t/'motion_inventory.csv').open('w')as out:
 writer=csv.writer(out,lineterminator="\n");writer.writerow(['component','file','existing_animation_evidence','android_scale_dependency','direct_finger_evidence','integration_risk','status','validation'])
 for f in sorted(paths):
  lines=f.read_text().splitlines();evidence=[f'{i+1}: {s.strip()[:160]}'for i,s in enumerate(lines)if re.search(r'(?:ObjectAnimator|ValueAnimator)\.(?:of|set)|new (?:SpringAnimation|AnimatorSet)|\.animate\(|FlexyTouchFeedback|FlexyFrameMotion|FlexyMotionAnimator|FlexyBoundSpring',s)][:8]
  finger=[f'{i+1}: {s.strip()[:110]}'for i,s in enumerate(lines)if re.search(r'\b(onTouchEvent|dispatchTouchEvent|onScroll|onLongPressMove)\(',s)][:4]
  migrated=f.name in ['SignatureNavigationCell.java','FlexyMotionActivity.java','MatteTextSettingsCell.java','MatteTextCheckCell.java','MatteDetailSettingsCell.java']
  reaction=f.name=='ReactionsContainerLayout.java';popup=f.name=='ActionBarPopupWindow.java';tabs=f.name=='MainTabsLayout.java'
  scaled=any('ObjectAnimator.'in s or'ValueAnimator.'in s or '.animate('in s for s in lines)
  writer.writerow([f.stem,str(f.relative_to(r)),' | '.join(evidence)or'No direct animator construction found; inherited/delayed work requires review','Migrated draw compression: independent'if migrated else'Direct drag/settle/root pulse independent; child tab selection and inherited item layout retain native owners'if tabs else'Outer reaction progress independent; item/pull/press animators retain native owners'if reaction else'Only opted-in reaction popup dismissal independent; all other windows retain native owners'if popup else'At least one Android animator path; not migrated'if scaled else'Not established by this static inventory',' | '.join(finger)or'No direct override found; native/inherited handlers require review','Low: isolated drawing'if migrated else'High: preserve lifecycle/gesture/property ownership'if f.name in ['ActionBarLayout.java','ChatActivity.java','ReactionsContainerLayout.java','ChatMessageCell.java']else'Review before integration','MIGRATED_TOUCH_ONLY'if migrated else'MIGRATED_DRAG_SETTLE_PULSE_ONLY'if tabs else'MIGRATED_PROGRESS_ONLY'if reaction else'MIGRATED_REACTION_DISMISS_OPT_IN_ONLY'if popup else'NOT_MIGRATED','API35 isolated native tests; physical pending'if migrated or reaction or popup or tabs else'Static source references only; runtime pending'])
